An Urho3D application inherits from Application and overrides three methods:

```cpp
class MyApp : public Application
{
    URHO3D_OBJECT(MyApp, Application);
public:
    MyApp(Context* context) : Application(context) { }

    void Setup() override
    {
        // Set engine parameters BEFORE window creation
        engineParameters_[EP_WINDOW_TITLE] = "My Game";
        engineParameters_[EP_FULL_SCREEN] = false;
        engineParameters_[EP_WINDOW_RESIZABLE] = true;
        engineParameters_[EP_SOUND] = true;
    }

    void Start() override
    {
        // Create scene, UI, subscribe to events
        // Engine is fully initialized here
    }

    void Stop() override
    {
        // Cleanup before exit (optional)
    }
};

// Entry point macro
URHO3D_DEFINE_APPLICATION_MAIN(MyApp)
```

Order: Constructor → Setup() → Start() → [game loop] → Stop()
Setup() configures, Start() creates, Stop() cleans up.

```cpp
void MyApp::Setup()
{
    // Window
    engineParameters_[EP_WINDOW_TITLE] = "My Game";
    engineParameters_[EP_FULL_SCREEN] = false;
    engineParameters_[EP_WINDOW_WIDTH] = 1280;
    engineParameters_[EP_WINDOW_HEIGHT] = 720;
    engineParameters_[EP_WINDOW_RESIZABLE] = true;

    // Rendering
    engineParameters_[EP_VSYNC] = true;
    engineParameters_[EP_MULTI_SAMPLE] = 4;  // MSAA
    engineParameters_[EP_HIGH_DPI] = true;

    // Audio
    engineParameters_[EP_SOUND] = true;

    // Logging
    engineParameters_[EP_LOG_NAME] = GetSubsystem<FileSystem>()->
        GetAppPreferencesDir("urho3d", "logs") + "myapp.log";
    engineParameters_[EP_LOG_LEVEL] = LOG_DEBUG;

    // Headless (no window - for servers)
    engineParameters_[EP_HEADLESS] = false;

    // Resource paths
    engineParameters_[EP_RESOURCE_PREFIX_PATHS] = 
        ";../share/Resources;../share/Urho3D/Resources";
}
```

All EP_ constants are defined in EngineDefs.h. Set these ONLY in Setup(), not later.

Use the URHO3D_LOG macros — never printf or std::cout:

```cpp
#include <Urho3D/IO/Log.h>

URHO3D_LOGDEBUG("Debug: value = " + String(x));
URHO3D_LOGINFO("Player spawned at " + pos.ToString());
URHO3D_LOGWARNING("Low memory: " + String(freeMB) + " MB");
URHO3D_LOGERROR("Failed to load model: " + path);

// With format
URHO3D_LOGINFOF("Player %s scored %d", name.CString(), score);

// Raw Log subsystem
auto* log = GetSubsystem<Log>();
log->Write(LOG_INFO, "Direct log write");
```

Log levels: LOG_TRACE, LOG_DEBUG, LOG_INFO, LOG_WARNING, LOG_ERROR.
Logs go to the file set by EP_LOG_NAME and to the console.

Urho3D has its own String class. Use it everywhere:

```cpp
#include <Urho3D/Container/Str.h>

String name = "Player";
String greeting = "Hello " + name;
bool empty = name.Empty();
unsigned len = name.Length();

// Convert to C string
const char* cstr = name.CString();

// Number to string
String numStr = String(42);
String floatStr = String(3.14f);

// String to number
int val = ToInt(numStr);
float fval = ToFloat(floatStr);

// Contains / Find
bool has = name.Contains("lay");
unsigned pos = name.Find("yer");

// Comparison
if (name == "Player")
    DoStuff();

// Format
String formatted = ToString("%s scored %d points", name.CString(), score);

// Constants
String::EMPTY;  // empty string constant
```

Never use std::string in Urho3D code. The engine's String handles all conversions.

Urho3D has its own container types:

```cpp
#include <Urho3D/Container/Vector.h>
#include <Urho3D/Container/HashMap.h>

// Vector (like std::vector)
Vector<String> names;
names.Push("Alice");
names.Push("Bob");
for (unsigned i = 0; i < names.Size(); ++i)
    URHO3D_LOGINFO(names[i]);

// PODVector for plain data (pointers, ints, floats)
PODVector<Node*> results;
scene_->GetChildren(results, true);

// HashMap (like std::unordered_map)
HashMap<StringHash, int> scores;
scores["player1"] = 100;
if (scores.Contains("player1"))
    int s = scores["player1"];

// HashSet (like std::unordered_set)
HashSet<unsigned> visited;
visited.Insert(nodeId);
if (visited.Contains(nodeId))
    Skip();

// Pair
Pair<String, int> entry("name", 42);
```

Use Urho3D containers in engine code — they're lighter than STL and integrate with the engine's memory management.

Variant is a type-safe union that can hold any common type:

```cpp
// Store different types
Variant intVar(42);
Variant floatVar(3.14f);
Variant strVar(String("hello"));
Variant vecVar(Vector3(1, 2, 3));
Variant boolVar(true);

// Read back (must use correct getter)
int i = intVar.GetInt();
float f = floatVar.GetFloat();
String s = strVar.GetString();
Vector3 v = vecVar.GetVector3();
bool b = boolVar.GetBool();

// VariantMap = HashMap<StringHash, Variant>
VariantMap data;
data["name"] = String("sword");
data["damage"] = 25;
data["position"] = Vector3(10, 0, 5);

// Reading from VariantMap (common in event handlers)
String name = data["name"].GetString();
int dmg = data["damage"].GetInt();

// VariantVector = Vector<Variant>
VariantVector list;
list.Push(Variant(1));
list.Push(Variant("hello"));
```

VariantMap is used everywhere: event data, attributes, serialization, network messages.

Define the event hash and parameter constants, then send/subscribe:

```cpp
// In a header (e.g., GameEvents.h)
URHO3D_EVENT(E_PLAYER_DIED, PlayerDied)
{
    URHO3D_PARAM(P_PLAYERID, PlayerId);   // unsigned
    URHO3D_PARAM(P_POSITION, Position);   // Vector3
    URHO3D_PARAM(P_KILLER, Killer);       // String
}

// SENDING the event
VariantMap& eventData = GetEventDataMap();
eventData[PlayerDied::P_PLAYERID] = playerId;
eventData[PlayerDied::P_POSITION] = node_->GetPosition();
eventData[PlayerDied::P_KILLER] = killerName;
SendEvent(E_PLAYER_DIED, eventData);

// SUBSCRIBING to the event
SubscribeToEvent(E_PLAYER_DIED, URHO3D_HANDLER(GameUI, HandlePlayerDied));

// HANDLER
void GameUI::HandlePlayerDied(StringHash eventType, VariantMap& eventData)
{
    using namespace PlayerDied;
    unsigned pid = eventData[P_PLAYERID].GetUInt();
    Vector3 pos = eventData[P_POSITION].GetVector3();
}
```

Events are the backbone of Urho3D's decoupled architecture. Components communicate through events, not direct calls.

```cpp
auto* cache = GetSubsystem<ResourceCache>();
auto* renderer = GetSubsystem<Renderer>();

// Load deferred render path
SharedPtr<RenderPath> renderPath(new RenderPath());
renderPath->Load(cache->GetResource<XMLFile>("RenderPaths/Deferred.xml"));

// Apply to viewport
SharedPtr<Viewport> viewport(new Viewport(context_, scene_, camera));
viewport->SetRenderPath(renderPath);
renderer->SetViewport(0, viewport);

// Or via command line:
// ./myapp -renderpath RenderPaths/Deferred.xml
```

Deferred rendering uses a G-Buffer pass (geometry → 4 render targets) then a lighting pass (light volumes read G-Buffer). Better for many lights. Forward rendering is default and simpler.

Render path XML files define the sequence of passes, render targets, and post-processing effects.

```cpp
auto* cache = GetSubsystem<ResourceCache>();

// Load from file (most common)
auto* mat = cache->GetResource<Material>("Materials/Stone.xml");

// Create programmatically
SharedPtr<Material> mat(new Material(context_));
mat->SetTechnique(0, cache->GetResource<Technique>("Techniques/DiffNormal.xml"));
mat->SetTexture(TU_DIFFUSE, cache->GetResource<Texture2D>("Textures/Stone.png"));
mat->SetTexture(TU_NORMAL, cache->GetResource<Texture2D>("Textures/Stone_Normal.png"));
mat->SetShaderParameter("MatDiffColor", Color(1, 1, 1, 1));
mat->SetShaderParameter("MatSpecColor", Vector4(0.5f, 0.5f, 0.5f, 16.0f));

// Clone and modify an existing material
SharedPtr<Material> clone = mat->Clone();
clone->SetShaderParameter("MatDiffColor", Color::RED);

// Apply to model
staticModel->SetMaterial(clone);
```

Texture units: TU_DIFFUSE, TU_NORMAL, TU_SPECULAR, TU_EMISSIVE, TU_ENVIRONMENT.
Always Clone() before modifying a cached material — otherwise you change it for everything.
